  function updateConsentSummary(){const terms=$$('#terms-consent-dialog .consent-document-copy h3').find(item=>item.textContent==='Serviço e aceite');if(terms?.nextElementSibling)terms.nextElementSibling.textContent='WorldForge é um app estático para criar mundos. É necessário autenticar-se para acessar a área de trabalho; mundos, perfil e preferências são salvos automaticamente na sua conta.';const privacy=$$('#terms-consent-dialog .consent-document-copy h3').find(item=>item.textContent==='Dados e cookies');if(privacy?.nextElementSibling)privacy.nextElementSibling.textContent='Mundos, fichas, anotações, perfil (foto e banner) e preferências são salvos automaticamente no Supabase e isolados por conta. O navegador mantém a sessão, o aceite e a escolha de cookies. Dados antigos locais só são enviados por importação explícita. Quando ativados, conteúdos de fórum e resumos publicados ficam públicos; guildas são privadas para participantes convidados. Denúncias são armazenadas para triagem manual. O resumo da Vitrine não inclui o arquivo completo, personagens, missões, eventos ou anotações. O projeto fica em us-east-1 (N. Virginia, EUA); processamentos auxiliares, como logs operacionais e suporte, podem ocorrer fora dela. O armazenamento de arquivos do Supabase não é usado. Consulte Privacidade nas Configurações. Cookie essencial lembra sua escolha por até 180 dias. Não há analytics, publicidade, IA conectada ou pagamentos.';$('#terms-consent-dialog .consent-record-note').textContent=`Registramos a versão ${TERMS_VERSION} e a data do aceite neste navegador. Você pode rever ou revogar o aceite nas Configurações.`;}
