  function makeEvent(data,rng,id,turn){const model=pick(rng,eventModels),city=pick(rng,data.cidades),cityNpcs=data.npcs.filter(n=>n.cidade_id===city.id),npc=cityNpcs.length&&rng()<.45?pick(rng,cityNpcs):null,duration=int(rng,2,6);return{id,tipo:model.tipo,titulo:`${model.titulo} — ${city.nome}`,descricao:model.descricao,impacto:model.impacto,cidade_id:city.id,reino_id:city.reino_id,npc_envolvido_id:npc?.id??null,turno_inicio:turn,duracao_turnos:duration,turno_fim:turn+duration,estado:'ativo'};}
